///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        let parentWin = $c.frame.path("../");
        const vHeadString = "NO:STRING(20),ISU_KOR_NM:STRING(200),DATA:STRING(500)";
        let faultCount = 0;
        // dts_List.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인

        // ------------------------------------------- 여기까지 공통 ---------------------------------------------
        // ------------------------------------------- 서버로직 -------------------------------------
        if (parentWin.logicPackYn === 'N') {
            await scwin.logicCheckServerSingle(parentWin.vBzProcsNo, parentWin.logicBizTyp);
        } else if (parentWin.logicPackYn === 'Y') {
            await scwin.logicCheckServerMulti();
            if (scwin.vListBzTpCd === '1') {
                // 예비,신규상장
                parentWin.grd_List_1.setBroadcast(true);
            } else if (scwin.vListBzTpCd === '2') {
                // 추가예비, 추가상장
                parentWin.grd_List_2.setBroadcast(true);
            }
        }
        // ------------------------------------------- 서버로직 -------------------------------------
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05931.onpageload" });
    }
};

