scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        let faultCount = 0;
        if (dts_List.getRowCount() > 0) {
            faultCount = dts_List.getCellData(CountRow, "TOTAL_CNT");
        }
        txb_LogicResult.setValue("총 " + faultCount + "종목에서 로직 오류가 발생하였습니다.");
        scwin.resetLogicChecked();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05931.dts_List_OnLoadCompleted" });
    }
};

