///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name logicCheckAdd
 * @description logic Check Add 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.logicCheckAdd = async function() {
    $c.elw.fn_elwaddisu_read_sync(dts_Isu, scwin.gBzNo);
    scwin.gIsuCd = dts_Isu.getCellData(1, "ISU_CD");
    scwin.gIsurCd = dts_Isu.getCellData(1, "ISUR_CD");
    scwin.gisuAbbrv = dts_Isu.getCellData(1, "ISU_KOR_ABBRV");
    scwin.gisuEngAbbrv = dts_Isu.getCellData(1, "ISU_ENG_ABBRV");
    scwin.gIsuSrtCd = dts_Isu.getCellData(1, "ISU_SRT_CD");

    // by nhkw  20190726
    if (scwin.gisuAbbrv.indexOf(scwin.gIsuSrtCd.substring(scwin.gIsuSrtCd.length - 4, scwin.gIsuSrtCd.length)) === -1 ||
        scwin.gisuEngAbbrv.indexOf(scwin.gIsuSrtCd.substring(scwin.gIsuSrtCd.length - 4, scwin.gIsuSrtCd.length)) === -1) {
        scwin.vText = "종목약명의 일련번호와 단축코드가 일치하지 않습니다.";
        scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    await scwin.monthDateCheck(dts_Isu.getCellData(1, "EXP_DD"));
    const gApplDd = dts_Isu.getCellData(1, "LIST_BZ_APPL_DD");
    // alert('gApplDd'+gApplDd);
    const gPreMonthExpDd = dts_CheckDate.getCellData(1, "CALND_DD");

    //    if ( parseInt(gApplDd, 10) > parseInt(gPreMonthExpDd, 10) ) {
    //        vText = "신청일이 만기일 1개월이전이 아닙니다.("+dateForm(gApplDd) + ") : (" + dateForm(gPreMonthExpDd)+")";
    //        fn_gridAddRow(gisuAbbrv, vText);
    //    }

    // 추가상장신청예정일이 1개월이 아닌지 체크 수정 jackal_12.06.08
    const gListApplSchdlDd = dts_Isu.getCellData(1, "LIST_APPL_SCHDL_DD");
    if (dts_Isu.getCellData(1, "LIST_BZ_TP_CD") === "004") // 추가 예비심사 청구인 경우만 체크수정

    {
        if (parseInt(gListApplSchdlDd, 10) > parseInt(gPreMonthExpDd, 10)) {
            scwin.vText = "추가상장신청일이 만기일 1개월이전이 아닙니다.(" + scwin.dateForm(gListApplSchdlDd) + ") : (" + scwin.dateForm(gPreMonthExpDd) + ")";
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
    const sbmOptions = {
        id : "sbm_dts_CheckDate",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_CheckDate=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_Isu.getCellData(1, "LIST_BZ_TP_CD") === "004") // 추가 예비심사 청구인 경우만 체크수정

    {
        // 예심청구일 직전영업일에서 당일로 체크 로직 변경
        // jackal_11.03.04
        if (dts_CheckDate.getCellData(1, "OUT_RATE_YN") === 'N') {
            //    vText = "청구일전일 기준 당행종목이 80%이상 매출되지 않았습니다."+dts_CheckDate.NameString(1, "OUT_RATE");
            scwin.vText = "예심 청구일 당일 기준 당해종목이 80%이상 매출되지 않았습니다." + dts_CheckDate.getCellData(1, "OUT_RATE");
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
    scwin.elwFncCheck();

    /*2009.10.12 ELW 추가상장 접수시 체크로직 추가
    	최초 발행총액(ISU_TOTAMT), 추가발행총액(ADD_ISU_TOTAMT)
     */
    if ((dts_Isu.getCellData(1, "ISU_TOTAMT") - dts_Isu.getCellData(1, "ADD_ISU_TOTAMT")) < 0) {
        scwin.vText = "추가발행총액이 신규상장 시 발행총액보다 큽니다.";
        scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    //    추가 발행총액이 10억 만인 경우도 체크 jackal_11.03.04
    if (dts_Isu.getCellData(1, "ADD_ISU_TOTAMT") < 1000000000) {
        scwin.vText = "추가발행총액이 10억 미만입니다.";
        scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    if (dts_Isu.getCellData(1, "ISU_CD").substring(5, 6) === "1" && dts_Isu.getCellData(1, "ISU_TOTAMT") < 1000000000) {
        /* 30억원에서 10억원 이상으로 완화 2012.12.31 */
        scwin.vText = "발행총액이 10억 미만입니다.";
        scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }

    // 상장제한종목 체크추가 jackal_11.03.04
    await scwin.listLimitIsuAddCheck();
    // KOSPI200 구성종목으로 체크 jackal_11.04.12 추가상장도 체크추가
    await scwin.kospi200CheckAdd(scwin.gBzNo);

    // 기초자산이 1(주식)일 경우 1년이내 투자주의종목지정 체크
    if (dts_Isu.getCellData(1, "ISU_CD").substring(5, 6) === "1") {
        await scwin.elwInvstgcautnCheck();
    }

    // SrM-000191426_ELW 상장공시시스템 전산개발 요청 by nhkw 20190726
    if (dts_Isu.getCellData(1, "LIST_BZ_TP_CD") === "005") {
        let url = "";
        url += "&BZ_PROCS_NO=" + scwin.gBzNo;
        url += "&BZ_PROCS_NO=" + scwin.gBzNo;
        const sbmOptions = {
            id : "sbm_dts_CorrYn",
            action : "/ElwListedReceive.do",
            ref : "",
            target : "dts_CorrYn=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        if (scwin.checkCorrYn() === "X") {
            scwin.vText = "예비심사 승인 종목정보와 신규상장 신청 종목정보가 일치하지 않습니다.";
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
    // txb_LogicResult.value = "총 "+dts_List.countRow +"종목에서 로직점검이 발생했습니다."

};

/**
 * @method
 * @name logicCheckNew
 * @description logic Check New 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.logicCheckNew = async function() {
    $c.elw.fn_elwisu_read_sync(dts_Isu, scwin.gBzNo);
    scwin.gIsuCd = dts_Isu.getCellData(1, "ISU_CD");
    scwin.gIsurCd = dts_Isu.getCellData(1, "ISUR_CD");
    scwin.gisuAbbrv = dts_Isu.getCellData(1, "ISU_KOR_ABBRV");
    scwin.gisuEngAbbrv = dts_Isu.getCellData(1, "ISU_ENG_ABBRV");
    scwin.gIsuSrtCd = dts_Isu.getCellData(1, "ISU_SRT_CD");

    // SrM-000191426 by nhkw  20190726
    if (scwin.gisuAbbrv.indexOf(scwin.gIsuSrtCd.substring(scwin.gIsuSrtCd.length - 4, scwin.gIsuSrtCd.length)) === -1 ||
        scwin.gisuEngAbbrv.indexOf(scwin.gIsuSrtCd.substring(scwin.gIsuSrtCd.length - 4, scwin.gIsuSrtCd.length)) === -1) {
        scwin.vText = "종목단축코드와 한글/영문종목약명이 일치하지 않습니다.";
        scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    await scwin.checkIsuDdAndExpDd(scwin.gIsuCd, scwin.gBzNo);

    // 조기종료일 경우  산정발행가액에 제반비용을 더해야 한다.
    // 2010.10.08
    let str = (dts_Isu.getCellData(1, "ISU_PRC") - dts_Isu.getCellData(1, "CALC_ISU_PRC")) / dts_Isu.getCellData(1, "CALC_ISU_PRC") * 100;

    // SrM-000191426_ELW 상장공시시스템 전산개발 요청 by nhkw 20190726  문구 수정
    if (dts_Isu.getCellData(1, "ELW_RGHT_TP_KIND_CD") === "3") {
        // 조기종료

        if ((dts_Isu.getCellData(1, "ISU_PRC") - dts_Isu.getCellData(1, "KO_CALC_ISU_PRC")) / dts_Isu.getCellData(1, "KO_CALC_ISU_PRC") * 100 > 20) {
            scwin.vText = "(발행가액-산정발행가액)/(산정발행가액)이 20% 초과했습니다.";
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
        if ((dts_Isu.getCellData(1, "ISU_PRC") - dts_Isu.getCellData(1, "KO_CALC_ISU_PRC")) / dts_Isu.getCellData(1, "KO_CALC_ISU_PRC") * 100 < -20) {
            scwin.vText = "(발행가액-산정발행가액)/(산정발행가액)이 (-20%) 미만입니다.";
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    } else {
        if ((dts_Isu.getCellData(1, "ISU_PRC") - dts_Isu.getCellData(1, "CALC_ISU_PRC")) / dts_Isu.getCellData(1, "CALC_ISU_PRC") * 100 > 20) {
            scwin.vText = "(발행가액-산정발행가액)/(산정발행가액)이 20% 초과했습니다.";
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
        if ((dts_Isu.getCellData(1, "ISU_PRC") - dts_Isu.getCellData(1, "CALC_ISU_PRC")) / dts_Isu.getCellData(1, "CALC_ISU_PRC") * 100 < -20) {
            scwin.vText = "(발행가액-산정발행가액)/(산정발행가액)이 (-20%) 미만입니다.";
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }

    // 발행일 /납일일/ 청약일 일치 여부
    if (dts_Isu.getCellData(1, "ISU_DD") !== dts_Isu.getCellData(1, "SUBS_DD") ||
        dts_Isu.getCellData(1, "ISU_DD") !== dts_Isu.getCellData(1, "PAY_DD")) {
        scwin.vText = "발행일/납일일/청약일 정보가 일치하지 않습니다.";
        scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    await scwin.holdyYn('발행일', dts_Isu.getCellData(1, "ISU_DD"));
    await scwin.holdyYn('만기일', dts_Isu.getCellData(1, "EXP_DD"));
    await scwin.holdyYn('행사개시일', dts_Isu.getCellData(1, "EXER_STRT_DD"));
    await scwin.holdyYn('행사종료일', dts_Isu.getCellData(1, "EXER_END_DD"));
