    }

    // ELW LP 호가 최종거래일 포함 마지막 5거래일 전까지 공급기간 확대 jackal_10.12.06
    await scwin.lPEndDtAsLastTrDtCheck(dts_Isu.getCellData(1, "ELW_LSTTRD_DD"));
    const gLpEndDdCnlDD = dts_CheckDate.getCellData(1, "CALND_DD");
    if (dts_Isu.getCellData(1, "ISU_CD").substring(5, 6) === "1" && (gLpEndDd !== gLpEndDdCnlDD)) {
        scwin.vText = "유동성공급종료일이 최종거래일을 포함한 마지막 5거래일 직전영업일이 아닙니다.(" + scwin.dateForm(gLpEndDdCnlDD) + ")";
        scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }

    // fn_MonthDateCheck(gLpEndDd);

    // var gLpEndDdCnlDD  = dts_CheckDate.NameString(1, "CALND_DD");
    // if ( dts_Isu.NameString(1, "ISU_CD").substring(5, 6) == "1"  && (gLpEndDd != gLpEndDdCnlDD)) {
    //            vText = "유동성공급종료일은 만기일 기준으로 한달전 직전영업일이 아닙니다.("+dateForm(gLpEndDdCnlDD)+")";
    // fn_gridAddRow(gisuAbbrv, vText);
    // }

    // ELW 제3자 LP 체크  jackal_10.12.14
    await scwin.thrdLPCheck();
    const gIsuLpSameYn = dts_CheckDate.getCellData(1, "ISU_LP_SAME_YN");
    if (gIsuLpSameYn === "N") {
        scwin.vText = "발행회사와 유동성공급자가 다릅니다.(" + dts_CheckDate.getCellData(1, "ISUCO_LP_NM") + ")";
        scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
    scwin.elwFncCheck();

    // 조기종료형이면 jackal 10.06.15
    if (dts_Isu.getCellData(1, "ELW_RGHT_TP_KIND_CD") === "3") {
        scwin.knockOutCheck();
    }

    // 7.권리유형이 표준형인데  조기종료발생기준가격이 입력된 경우 jackal 10.06.15
    if (dts_Isu.getCellData(1, "ELW_RGHT_TP_KIND_CD") === "1" && dts_Isu.getCellData(1, "ELW_KO_OCCR_BAS_PRC") !== 0) {
        scwin.vText = "권리유형이 표준형인데  조기종료발생기준가격이 입력되어 있습니다.";
        scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }

    // 기준가격결정일 항목이 공란이면
    if (dts_Isu.getCellData(1, "ELW_ULY_BAS_PRC_DECSN_DD") === "") {
        scwin.vText = "기준가격결정일이 공란입니다.";
        scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
    } else {
        // 가격결정기준일의 종가 체크
        if (scwin.svrGubun === "dr") {
            // DR일 경우
            scwin.vText = "DR에서 운영될때는 기준가격결정일의 종가를 비교 할 수 없습니다.";
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        } else {
            await scwin.jongGaCheck(dts_Isu.getCellData(1, "ISU_CD").substring(5, 6), dts_Isu.getCellData(1, "ELW_ULY_BAS_PRC_DECSN_DD"), dts_Isu.getCellData(1, "ELW_ULY_BAS_PRC"));
        }
    }

    // 만기평가가격/지수 내용이 표준문구와 다른지 체크
    if (dts_Isu.getCellData(1, "ISU_CD").substring(5, 6) === "3") // 기초자산이 주가지수이면

    {
        if (dts_Isu.getCellData(1, "ELW_EXP_VALU_PRC_METHD") !== "최종거래일 종가") {
            scwin.vText = "만기평가가격/지수 항목이 표준문구와 다릅니다.";
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    } else

    // 기초자산이 주식이면

    {
        if (dts_Isu.getCellData(1, "ELW_EXP_VALU_PRC_METHD") !== "최종거래일포함 직전 5영업일 종가의 산술평균") {
            scwin.vText = "만기평가가격/지수 항목이 표준문구와 다릅니다.";
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }

    // 기상장종목과의 일치여부 체크
    // 업무처리번호를 보내서 일치하는 종목의 종목약명 리턴
    await scwin.gIListYNCheck();

    // 기신청종목과의 일치여부 체크
    // 업무처리번호를 보내서 일치하는 미처리종목의 종목약명 리턴
    await scwin.gISinchungYNCheck();

    // 지수ELW 일때 전환비율 100 체크
    // 행사가격의 간격이 2.5포인트의 등간격이 아닐경우 로직체크

    // 지수,주식 둘다 체크 2014.10.31 { 최종거래일 체크 (옵션만기일과 일치여부 체크) jackal_11.06.10 }
    await scwin.lstTrdOptExpCheck();
    if (dts_Isu.getCellData(1, "ISU_CD").substring(5, 6) === "3") // 기초자산이 주가지수이면

    {
        if (dts_Isu.getCellData(1, "ELW_OBJ_IDX_TP_CD") === "1") // kospi 200 이면(jackal_16.06.30)

        {
            if (dts_Isu.getCellData(1, "ELW_CONV_RTO") !== 100) {
                scwin.vText = "지수 ELW 전환비율이 100 이 아닙니다.";
                scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
            }
            if (dts_Isu.getCellData(1, "ELW_EXER_PRC_25_TERM_YN") !== "Y") {
                scwin.vText = "지수 ELW 행사가격의 간격이 2.5포인트의 등간격이 아닙니다.";
                scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
            }
        } else if (dts_Isu.getCellData(1, "ELW_OBJ_IDX_TP_CD") === "5") // kosdaq 150 이면 (jackal_16.06.30)

        {
            if (dts_Isu.getCellData(1, "ELW_CONV_RTO") !== 10) {
                scwin.vText = "지수 ELW 전환비율이 10 이 아닙니다.";
                scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
            }
            if (dts_Isu.getCellData(1, "ELW_EXER_PRC_25_TERM_YN") !== "Y") {
                scwin.vText = "지수 ELW 행사가격의 간격이 10포인트의 등간격이 아닙니다.";
                scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
            }
        }

        // 수정 2014.10.31 기초자산이주가지수이면서 기준가격결정일이 예심청구일 2주 전인지 체크
        if (dts_Isu.getCellData(1, "LIST_BZ_TP_CD") === "002" && dts_Isu.getCellData(1, "ELW_ULY_BAS_PRC_DECSN_14DD_YN") === "Y") {
            scwin.vText = "기준가격결정일이 예비심사청구일 전 2주 이내의 날이 아닙니다.";
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
    if (dts_Isu.getCellData(1, "ISU_CD").substring(5, 6) === "1") // 기초자산이 주식이면

    {
        // 추가 2014.10.31(기초자산이 주식인 경우, 기준가격 결정일이 가장최근 최종거래일의 전주  금요일인지 체크(보통 매달 첫째주 금요일))
        await scwin.fbasprcDecsnDayCheck();

        // 추가 2014.10.31 (기조차산이 주식인경우,해당 기준가격 범위의 전환비율이 아닌경우 체크)
        /*
        	 10,000 이하 : 0.1
        	 10,000초과 ~ 20,000이하:0.05
        	 20,000초과 ~ 50,000이하:0.02
        	 50,000초과~ 100,000이하:0.01
        	100,000초과~ 200,000이하:0.005
        	200,000초과~ 500,000이하:0.002
        	500,000초과:  0.001
     */
        if (dts_Isu.getCellData(1, "CONV_RTO_YN") === "Y") {
            scwin.vText = "기준가격(" + $c.stf.addComma(dts_Isu.getCellData(1, "ELW_ULY_BAS_PRC")) + ")에 해당하는 전환비율(" + dts_Isu.getCellData(1, "ELW_CONV_RTO") + ")이 일치하지 않습니다.";
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
        if (dts_Isu.getCellData(1, "PERITY_RT") >= 110) {
            await scwin.elwBasPerityCheck110();
        } else {
            // 추가 2014.10.31 주식ELW 행사가격이 기준 패리티로부터 산출된 값인지 체크
            await scwin.elwBasPerityCheck();
        }
    }

    // 수정 2014.10.31 극외가격 90 % 미만 체크
    // 극외가격 85 % 미만 체크 jackal_11.06.10
    if (dts_Isu.getCellData(1, "PERITY_90RT_YN") === "Y") {
        scwin.vText = "패리티가 90% 미만입니다.";
        scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }

    // 기초자산이 1(주식)일 경우 1년이내 투자주의종목지정 체크
    if (dts_Isu.getCellData(1, "ISU_CD").substring(5, 6) === "1") {
        await scwin.elwInvstgcautnCheck();
    }

    // 기초자산별 역사적변동성 산출 후 적용변동성 체크
    await scwin.histVoltCheck();

    // 기초자산이 주식인데 기초주권명이 공란인 경우 jackal_150622
    if (dts_Isu.getCellData(1, "ISU_CD").substring(5, 6) === "1") // 기초자산이 주식이면

    {
        $c.elw.fn_elwUly_read_sync(dts_UlyIsu, scwin.gBzNo);
        if (dts_UlyIsu.getCellData(1, "ULY_ISU_NM") === "") {
            scwin.vText = "기초자산이 주식인데 기초주권명이 공란입니다.";
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }

    // SrM-000191426_ELW 상장공시시스템 전산개발 요청 by nhkw 20190726
    if (dts_Isu.getCellData(1, "LIST_BZ_TP_CD") === "003" || dts_Isu.getCellData(1, "LIST_BZ_TP_CD") === "005") {
        let url = "";
        url += "&BZ_PROCS_NO=" + scwin.gBzNo;
        url += "&BZ_PROCS_NO=" + scwin.gBzNo;
        const sbmOptions = {
            id : "sbm_dts_CorrYn",
            action : "/ElwListedReceive.do",
            ref : "",
            target : "dts_CorrYn=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        if (scwin.checkCorrYn() === "X") {
            scwin.vText = "예비심사 승인 종목정보와 신규상장 신청 종목정보가 일치하지 않습니다.";
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
    txb_LogicResult.setValue("총 " + dts_List.getRowCount() + "종목에서 로직점검이 발생했습니다.");
};

/**
 * @method
 * @name elwInvstgcautnCheck
 * @description elw Invstgcautn Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.elwInvstgcautnCheck = async function() {
    const sbmOptions = {
        id : "sbm_dts_invstgCautn",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_invstgCautn=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let outText = '';
    for (let idx = 1; idx <= dts_invstgCautn.getRowCount(); idx++) {
        const comNm = dts_invstgCautn.getCellData(idx, "INVSTCAUTN_ISU_COM_NM");
        const procDate = dts_invstgCautn.getCellData(idx, "INVSTCAUTN_ISU_PROC_DATE");
        const procFormNm = dts_invstgCautn.getCellData(idx, "FORM_KOR_NM");

        // outText += "회사명: " + comNm + " 처리일: " + procDate + " " ;
        outText += "'" + comNm + "'은 " + procDate + "에";
    }
    if (outText !== '') {
        scwin.vText = "해당 기초자산 " + outText + " " + procFormNm + "으로 되었습니다.";
        scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
    }
};

