        if (dts_CheckDate.getCellData(1, "ELW_BAS_PCPARITY_YN") === "N") {
            scwin.vText = "주식ELW 행사가격(" + $c.stf.addComma(dts_Isu.getCellData(1, "ELW_EXER_PRC")) + ")이 기준패리티로부터 산출된 값과 일치하지 않습니다.";
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    } else if (dts_Isu.getCellData(1, "ELW_RGHT_TP_CD") === "P") {
        const sbmOptions = {
            id : "sbm_dts_CheckDate",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_CheckDate=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        if (dts_CheckDate.getCellData(1, "ELW_BAS_PCPARITY_YN") === "N") {
            scwin.vText = "주식ELW 행사가격(" + $c.stf.addComma(dts_Isu.getCellData(1, "ELW_EXER_PRC")) + ")이 기준패리티로부터 산출된 값과 일치하지 않습니다.";
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
};

