/**
 * @method
 * @name jongGaCheck
 * @description jong Ga Check 처리
 * @param {*} vJisuGubun vJisuGubun
 * @param {*} vDeciStdDt vDeciStdDt
 * @param {*} vStdPrc vStdPrc
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.jongGaCheck = async function(vJisuGubun, vDeciStdDt, vStdPrc) {
    if (vJisuGubun === "3") // 기초자산이 주가지수이면

    {
        let url = "";
        if (dts_Isu.getCellData(1, "ELW_OBJ_IDX_TP_CD") === "5") {
            //    KOSDAQ150
            url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_RECV_LOGICCHECK_JISU_CLS_PRC_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.logiccheck.jisucls.condition" + "&{P}param01=" + "Q5G01P" + // Q5G01P  2 203
                "&{P}param02=" + vDeciStdDt;
            dts_CheckDate.DataID = encodeURI(url);
            dts_CheckDate.reset();
        } else if (dts_Isu.getCellData(1, "ELW_OBJ_IDX_TP_CD") === "1") {
            // 코스피200
            url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_RECV_LOGICCHECK_JISU_CLS_PRC_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.logiccheck.jisucls.condition" + "&{P}param01=" + "K2G01P" + // K2G01P 1 028
                "&{P}param02=" + vDeciStdDt;
            dts_CheckDate.DataID = encodeURI(url);
            dts_CheckDate.reset();
        } else {
            //    나머지는 ...
            url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_RECV_LOGICCHECK_JISU_CLS_PRC_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.logiccheck.jisucls.condition" + "&{P}param01=" + "K2G01P" + // K2G01P 1 028
                "&{P}param02=" + vDeciStdDt;
            dts_CheckDate.DataID = encodeURI(url);
            dts_CheckDate.reset();
        }

        // 주가지수일경우  종가 체크
        let gJisuPrc = dts_CheckDate.getCellData(1, "ELW_JISU_CLS_PRC");
        if (gJisuPrc !== vStdPrc) {
            scwin.vText = "해당일의 기준가격 정보가 일치하지 않습니다 : " + vDeciStdDt + " 종가 " + gJisuPrc;
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    } else

    // 기초자산이 주식이면

    {
        const sbmOptions = {
            id : "sbm_dts_CheckDate",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_CheckDate=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 주가지수일경우  종가 체크
        let gJisuPrc = dts_CheckDate.getCellData(1, "ELW_JUSIK_CLS_PRC");
        if (gJisuPrc !== vStdPrc) {
            scwin.vText = "해당일의 기준가격 정보가 일치하지 않습니다 : " + vDeciStdDt + " 종가 " + gJisuPrc;
            scwin.gridAddRow(scwin.gisuAbbrv, scwin.vText);
        }
    }
};

