/**
 * @method
 * @name dateForm
 * @description date Form 처리
 * @param {String} pStr pStr
 * @returns {void}
 * @hidden N
 */
scwin.dateForm = function(pStr) {
    let str = pStr.substring(0, 4) + "년" + pStr.substring(4, 6) + "월" + pStr.substring(6, 8) + "일";
    return str;
};

/**
 * @method
 * @name gridAddRow
 * @description grid Add Row 처리
 * @param {*} gIsuAbbrv gIsuAbbrv
 * @param {String} pStr pStr
 * @returns {void}
 * @hidden N
 */
scwin.gridAddRow = function(gIsuAbbrv, pStr) {
    dts_List.insertRow();
    dts_List.setCellData(dts_List.getRowCount(), "ISU_KOR_NM", gIsuAbbrv);
    dts_List.setCellData(dts_List.getRowCount(), "DATA", pStr);
    scwin.gSuccess = false;
};

/**
 * @method
 * @name resetLogicChecked
 * @description reset Logic Checked 처리
 * @returns {void}
 * @hidden N
 */
scwin.resetLogicChecked = function() {
    let parentWin = $c.frame.path("../");
    if (parentWin.logicPackYn === 'Y') {
        let dtsObj = parentWin.fn_getDataSet();
        for (let i = 1; i <= dtsObj.getRowCount(); i++) {
            if (dtsObj.getCellData(i, "CHECK") === "T") {
                const isuKorNm = dtsObj.getCellData(i, "ISU_KOR_ABBRV");
                const Row = $c.cp.getNameValueRow(dts_List, "ISU_KOR_NM", isuKorNm);
                if (Row <= 0) {
                    dtsObj.setCellData(i, "CHECK", "F");
                }
            }
        }
    }
};
